//! G14 quota-sampler end-to-end parity: the Rust sampler (merge + backfill + record) on a fresh
//! Engine reproduces the TS writer's historyRecords (`tests/spec/analytics-writers/sampler-vectors.json`,
//! regenerated by `generate-sampler-vectors.mjs` against the in-process NAPI store — the same Engine).
mod common;

use aac_store::observe::account_identity;
use aac_store::sampler::{self, BackfillSource};
use aac_store::{ops, usage};
use common::temp_dir;
use serde_json::{Map, Value, json};
use sha2::{Digest, Sha256};

fn vectors() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/spec/analytics-writers/sampler-vectors.json"
    );
    let text = std::fs::read_to_string(path).expect("sampler-vectors.json (run the generator)");
    serde_json::from_str(&text).expect("vectors parse")
}

fn numbers(value: &Value) -> Value {
    match value {
        Value::Number(n) => json!(n.as_f64().expect("finite vector number")),
        Value::Array(list) => Value::Array(list.iter().map(numbers).collect()),
        Value::Object(map) => Value::Object(
            map.iter()
                .map(|(k, v)| (k.clone(), numbers(v)))
                .collect::<Map<String, Value>>(),
        ),
        other => other.clone(),
    }
}

fn sha256_hex(text: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(text.as_bytes());
    hasher.finalize().iter().map(|b| format!("{b:02x}")).collect()
}

#[test]
fn sampler_matches_the_ts_writer_end_to_end() {
    let doc = vectors();
    let now = doc["now"].as_i64().expect("now");
    let dir = temp_dir("g14-sampler");
    let engine = ops::open_engine(dir.to_str().unwrap(), None, None).expect("open engine");

    let dashboards = doc["dashboards"].as_array().expect("dashboards").clone();
    let merged = sampler::merge_accounts(&dashboards);
    let identities: Vec<String> = merged
        .iter()
        .map(|a| account_identity(a.as_object().expect("account object")).expect("identity"))
        .collect();
    let expected_ids: Vec<String> = doc["expectedMerged"]
        .as_array()
        .expect("expectedMerged")
        .iter()
        .map(|v| v.as_str().expect("identity string").to_string())
        .collect();
    assert_eq!(identities, expected_ids, "coalesced account order");

    // Reconstruct the backfill sources from the captured texts; the content hash must agree.
    let sources: Vec<BackfillSource> = doc["sources"]
        .as_array()
        .expect("sources")
        .iter()
        .map(|s| {
            let text = s["text"].as_str().expect("source text");
            let sha = sha256_hex(text);
            assert_eq!(sha, s["sha256"].as_str().expect("sha"), "source hash");
            let (records, parsed) = sampler::records_from_text(text);
            assert!(parsed, "source parsed");
            BackfillSource {
                label: s["label"].as_str().expect("label").to_string(),
                sha256: sha,
                records,
            }
        })
        .collect();

    let providers = sampler::providers_of(&merged);
    let report = sampler::backfill(&engine, &sources, &providers, now, 0).expect("backfill");
    assert_eq!(
        numbers(&json!(report)),
        numbers(&doc["expectedReport"]),
        "backfill report"
    );

    // A second backfill is a no-op: every source's hash is already imported.
    let again = sampler::backfill(&engine, &sources, &providers, now, 0).expect("backfill again");
    assert_eq!(again.files_already_imported, sources.len() as u64);
    assert_eq!(again.records, 0);

    sampler::record_sample(&engine, &merged, now).expect("record live");
    let history = ops::call(
        &engine,
        "historyRecords",
        &json!({
            "fromMs": 0,
            "toMs": now + 5 * 60_000,
            "nowMs": now,
            "thinning": { "kind": "history" }
        })
        .to_string(),
    )
    .expect("historyRecords");
    assert_eq!(
        numbers(&history),
        numbers(&doc["expectedHistory"]),
        "stored history equals the TS writer's"
    );

    // The live tick's tally is the store's own decision (sampled/seen/skipped/rejected).
    let tally = usage::record(&engine, sampler::sample_observations(&merged, now)).expect("tally");
    let _ = tally;
    std::fs::remove_dir_all(&dir).ok();
}

#[test]
fn unavailable_t3_quota_window_never_becomes_a_reading() {
    let dir = temp_dir("unavailable-t3-quota");
    let engine = ops::open_engine(dir.to_str().unwrap(), None, None).expect("open engine");
    let now = 1_794_700_800_000;
    let at = |ms| aac_num::ecma::to_iso_string(ms).expect("timestamp");
    let snapshot = |ms, used, cli| {
        json!({
            "id": "antigravity:fixture", "provider": "antigravity", "status": "ok", "source": "fixture", "host": "windows",
            "sampledAt": at(ms), "windows": [
                {"key": "gemini-weekly", "label": "Gemini weekly (app)", "poolId": "gemini-app", "usedPercent": used},
                cli,
            ]
        })
    };
    let first = snapshot(
        now,
        27,
        json!({
            "key": "cli-gemini-weekly", "label": "Gemini weekly (T3)", "poolId": "gemini-cli", "usedPercent": 40,
        }),
    );
    let later = now + 600_000;
    let failed = snapshot(
        later,
        28,
        json!({
            "key": "cli-gemini-weekly", "label": "Gemini weekly (T3)", "poolId": "gemini-cli",
            "status": "unavailable", "usedPercent": null,
        }),
    );
    assert_eq!(
        sampler::record_sample(&engine, &[first], now)
            .expect("first sample")
            .sampled,
        1
    );
    assert_eq!(
        sampler::record_sample(&engine, &[failed], later)
            .expect("later sample")
            .sampled,
        1
    );
    let history = ops::call(
        &engine,
        "historyRecords",
        &json!({
            "fromMs": now, "toMs": later, "nowMs": later, "thinning": { "kind": "history" }
        })
        .to_string(),
    )
    .expect("history");
    let records = history.as_array().expect("records");
    let windows = records
        .iter()
        .filter_map(|record| record["windows"].as_array())
        .flatten()
        .collect::<Vec<_>>();
    let cli = windows
        .iter()
        .filter(|window| window["key"] == "cli-gemini-weekly")
        .collect::<Vec<_>>();
    assert!(!cli.is_empty(), "the original CLI reading stays in history");
    assert!(cli.iter().all(|window| window["usedPercent"].as_f64() == Some(40.0)));
    assert!(
        windows
            .iter()
            .any(|window| window["key"] == "gemini-weekly" && window["usedPercent"].as_f64() == Some(28.0))
    );
    drop(engine);
    std::fs::remove_dir_all(&dir).ok();
}
